<template><div class="catalog-products min-h-screen bg-slate-50 px-4 py-8"><div class="mx-auto grid max-w-7xl gap-8 lg:grid-cols-[240px_1fr]"><CategorySidebar :categories="categoryGroups" :selected-category="selectedCategory" :expanded-parent-ids="expandedParentIds" :show-drawer="showFilterDrawer" :show-search="true" :search-query="searchQuery" @select-category="selectCategory" @toggle-parent="toggleParentCategory" @update:show-drawer="showFilterDrawer = $event" @update:search-query="searchQuery = $event" @clear-search="clearSearch"/><main><h1 class="mb-6 text-3xl font-black">{{ t('nav.products') }}</h1><div class="grid grid-cols-2 gap-4 md:grid-cols-3"><ProductCard v-for="(p,i) in products" :key="p.id" :product="p" :index="i" @click="go(p.slug)" @quick-buy="quickBuy" /></div><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></main></div></div></template>
<script setup lang="ts">import { onMounted, onUnmounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { useProductList } from '../../composables/useProductList'; import ProductCard from '../../components/ProductCard.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; import CategorySidebar from '../../components/CategorySidebar.vue'; const {t}=useI18n(); const router=useRouter(); const {products,selectedCategory,searchQuery,showFilterDrawer,expandedParentIds,categoryGroups,selectCategory,toggleParentCategory,clearSearch,initialize,cleanup}=useProductList({pageSize:18,homeRouteName:'products'}); const selected=ref<any>(null);const quickVisible=ref(false);const go=(s:string)=>router.push(`/products/${s}`);const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true};onMounted(()=>void initialize());onUnmounted(cleanup)</script>
